<?php
require 'config.php';require 'includes/functions.php';$specialty=trim($_GET['specialty']??'');$city=trim($_GET['city']??'');$sql="SELECT d.id doctor_id,d.specialty,d.consultation_fee,u.name doctor_name,h.id hospital_id,h.name hospital_name,h.city,h.address,COALESCE(AVG(r.rating),0) rating,COUNT(r.id) reviews FROM doctors d JOIN users u ON u.id=d.user_id JOIN hospitals h ON h.id=d.hospital_id LEFT JOIN reviews r ON r.doctor_id=d.id WHERE d.active=1 AND h.active=1";$args=[];if($specialty!==''){$sql.=" AND d.specialty LIKE ?";$args[]="%$specialty%";}if($city!==''){$sql.=" AND h.city LIKE ?";$args[]="%$city%";}$sql.=" GROUP BY d.id ORDER BY rating DESC,doctor_name";$q=$pdo->prepare($sql);$q->execute($args);$doctors=$q->fetchAll();$specs=$pdo->query("SELECT DISTINCT specialty FROM doctors WHERE active=1 ORDER BY specialty")->fetchAll(PDO::FETCH_COLUMN);$title='Find a doctor';require 'includes/header.php';?>
<div class="intro"><span class="tag">DOCTOR DIRECTORY</span><h1>Find the right care for you.</h1><p>Search by medical specialty or hospital location.</p></div><form class="search" method="get"><label>Specialty<select name="specialty"><option value="">All specialties</option><?php foreach($specs as $s):?><option <?=$specialty===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label><label>City / location<input name="city" value="<?=e($city)?>" placeholder="e.g. Chennai"></label><button class="btn">Search doctors</button></form>
<div class="grid"><?php foreach($doctors as $d):?><article class="card"><div class="symbol">⚕</div><span class="tag"><?=e($d['specialty'])?></span><h3>Dr. <?=e($d['doctor_name'])?></h3><p><b><?=e($d['hospital_name'])?></b><br><?=e($d['city'])?> · <?=e($d['address'])?></p><p>★ <?=number_format((float)$d['rating'],1)?> (<?=$d['reviews']?> reviews) · <?=rupee($d['consultation_fee'])?></p><a class="btn small" href="book.php?doctor=<?=$d['doctor_id']?>">Book appointment</a> <a href="hospital.php?id=<?=$d['hospital_id']?>">Hospital details</a></article><?php endforeach;?><?php if(!$doctors):?><p>No doctors match those filters.</p><?php endif;?></div><?php require 'includes/footer.php';?>